{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C03", "C17", "C16", "C45", "C50", "C46", "C64", "C65", "C61"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C03", "C17", "C16", "C45", "C50", "C64", "C65"],
  "claims": [
    {
      "claim": "The query is a tryptamine/triptan with a dimethylaminoethyl side chain and a pyrrolidine sulfonamide; the closest supplied analog zolmitriptan has high aqueous solubility (20.26 mg/mL at pH 1.2 and 9.79 mg/mL at pH 6.8), supporting favorable dissolution for this structural class.",
      "card_ids": ["C45", "C50"]
    },
    {
      "claim": "L5 gut-wall records show no efflux liability for the closest analog zolmitriptan: both apical-to-basolateral and basolateral-to-apical fluxes increased linearly with concentration, consistent with passive diffusion; imipramine also showed an efflux ratio of 1.1. No close-analog gut-wall efflux or intestinal-metabolism loss was identified.",
      "card_ids": ["C64", "C65", "C61"]
    },
    {
      "claim": "L1 gold contexts with indole/basic-amine or sulfonamide features support F >= 20%: vilazodone 72% in the fed state, 5-HTP 49% in humans, and sulthiame complete oral bioavailability. No transferable direct low-F outcome is present.",
      "card_ids": ["C03", "C17", "C16"]
    },
    {
      "claim": "The sulfonamide-pyrrolidine motif is compatible with good aqueous solubility, as shown by TPN729MA (30 mg/mL in water), supporting the dissolution component of oral absorption.",
      "card_ids": ["C46"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C64", "C65", "C61"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability or IV-comparator data for the query or a close analog.",
    "L3 sumatriptan AUC/Cmax records provide oral exposure but no IV comparator, so they cannot quantify F.",
    "No query-specific first-pass metabolism or clearance data; the dimethylaminoethyl tryptamine motif may undergo metabolism but is not quantified in the cards.",
    "No human PK, dose, formulation, or prandial-state data for the query.",
    "Solubility and transport records are for reference molecules, not the query; transfer is inferred from structural similarity."
  ],
  "decision_summary": "L5 gut-wall records add supportive transport evidence for the closest analog zolmitriptan (passive diffusion, no efflux) and show no close-analog gut-wall loss; combined with favorable solubility records, supportive L1 gold contexts, and the favorable physicochemical prior, and absent any transferable direct low-F outcome, the prediction remains high with moderate confidence."
}

